// RootView adapts a fully prepared Config to the generated consumer-view interfaces.
// Its single pointer preserves identity across facade narrowing without interface boxing allocations.
// The generation identifies the release the view was sampled from; it is part of
// the view's identity, so two views of one config from different generations are
// distinct GenerationMemo keys. Construct once per immutable generation and reuse the view.
type RootView struct {
	g *rootGeneration
}

type rootGeneration struct {
	config     *Config
	generation Generation
}

// NewRootView wraps a fully prepared configuration root that carries no
// release metadata. It panics immediately when config is nil so an invalid
// startup composition cannot survive until a later accessor dereference.
func NewRootView(config *Config) RootView {
	if config == nil {
		panic("config invariant config_root_present violated: NewRootView requires non-nil config")
	}
	return RootView{g: &rootGeneration{config: config}}
}

// NewRootViewWithGeneration wraps a fully prepared configuration root together
// with the identity of the generation it was sampled from. It panics immediately
// when config is nil.
func NewRootViewWithGeneration(config *Config, generation Generation) RootView {
	if config == nil {
		panic("config invariant config_root_present violated: NewRootViewWithGeneration requires non-nil config")
	}
	return RootView{g: &rootGeneration{config: config, generation: generation}}
}

// ConfigGeneration returns the generation the view was sampled from; it is zero for
// views built with NewRootView.
func (v RootView) ConfigGeneration() Generation {
	if v.g == nil {
		return Generation{}
	}
	return v.g.generation
}

